353	#[cfg(test)]
354	mod tests {
355	    use super::*;
356	    use crate::view::snapshot::{ForceKind, LandscapeSnapshot, RecordSource, SnapshotForce};
357	    use crate::view::testing::{fixture_defense_snapshot, fixture_main_snapshot};
358	
359	    fn html(include_defense: bool) -> String {
360	        let snap = if include_defense {
361	            fixture_defense_snapshot()
362	        } else {
363	            fixture_main_snapshot()
364	        };
365	        render_landscape_html(&snap).expect("landscape html renders")
366	    }
367	
368	    /// The page carries its own data — no fetch, no sidecar files at view time.
369	    #[test]
370	    fn html_embeds_snapshot_json_in_a_script_block() {
371	        let out = html(false);
372	        assert!(
373	            out.contains(r#"<script id="residual-snapshot" type="application/json">"#),
374	            "snapshot must be embedded as an application/json script block"
375	        );
376	        assert!(out.contains("S-01"), "embedded snapshot must carry force ids");
377	        assert!(out.contains("queue-overload"), "shortnames must be embedded");
378	
379	        let json = extract_snapshot_json(&out).expect("snapshot json must be extractable");
380	        let parsed: LandscapeSnapshot =
381	            serde_json::from_str(json).expect("embedded snapshot must be valid LandscapeSnapshot json");
382	        assert_eq!(parsed.stressors.len(), 1);
383	        assert_eq!(parsed.stressors[0].id, "S-01");
384	    }
385	
386	    /// Filterable force list plus attractor grouping.
387	    #[test]
388	    fn html_contains_filterable_force_list_and_attractor_grouping() {
389	        let out = html(false);
390	        assert!(
391	            out.contains(r#"data-view="force-list""#),
392	            "force list view is missing"
393	        );
394	        assert!(
395	            out.contains("data-force-filter"),
396	            "force list must expose a filter input hook"
397	        );
398	        assert!(
399	            out.contains(r#"data-attractor-group="A-01""#),
400	            "forces must be groupable by attractor id"
401	        );
402	        assert!(
403	            out.contains(r#"data-force-id="S-01""#),
404	            "force rows must be addressable by force id"
405	        );
406	        assert!(
407	            out.contains(r#"data-force-kind="stressor""#),
408	            "force rows must expose kind for filtering"
409	        );
410	        assert!(
411	            out.contains(r#"data-architecture-set="iter1""#),
412	            "architecture_set must be exposed for filtering"
413	        );
414	    }
