416	    /// Matrix / heatmap affordance backed by data attributes.
417	    #[test]
418	    fn html_contains_residue_matrix_with_cell_data_attributes() {
419	        let out = html(false);
420	        assert!(out.contains(r#"data-view="matrix""#), "matrix view is missing");
421	        assert!(
422	            out.contains("data-residue-cell"),
423	            "matrix cells must be tagged data-residue-cell"
424	        );
425	        assert!(
426	            out.contains(r#"data-component="auth""#),
427	            "component columns must be addressable"
428	        );
429	        assert!(
430	            out.contains(r#"data-coupled="1""#),
431	            "the S-01 × auth coupling must render as a coupled cell"
432	        );
433	    }
434	
435	    /// Staging forms + copy surface + the JS that builds commands.
436	    #[test]
437	    fn html_contains_command_generator_and_copy_surface() {
438	        let out = html(false);
439	
440	        for target in ["stressor", "purpose", "attractor", "component"] {
441	            assert!(
442	                out.contains(&format!(r#"data-command-generator="{target}""#)),
443	                "missing staging form for {target}"
444	            );
445	        }
446	        assert!(
447	            out.contains("data-copy-commands"),
448	            "copy-commands surface is missing"
449	        );
450	        assert!(
451	            out.contains(r#"id="staged-commands""#),
452	            "staged command output element is missing"
453	        );
454	        assert!(
455	            out.contains("function buildAddCommand"),
456	            "JS command builder buildAddCommand is missing"
457	        );
458	        assert!(
459	            out.contains("function shellQuote"),
460	            "JS shell quoting helper shellQuote is missing"
461	        );
462	        assert!(
463	            out.contains("residual add "),
464	            "generated commands must be `residual add …`"
465	        );
466	        for flag in [
467	            "--description",
468	            "--attractor-id",
469	            "--naive-change",
470	            "--shortname",
471	            "--outcomes",
472	            "--positive-state",
473	            "--negative-state",
474	            "--architecture-set",
475	            "--status",
476	        ] {
477	            assert!(out.contains(flag), "command generator must emit {flag}");
478	        }
479	    }
480	
481	    /// The UI is read-only against the ledger: it stages text, it does not write.
482	    #[test]
483	    fn html_command_generator_does_not_mutate_the_ledger() {
484	        let out = html(false);
485	        for forbidden in ["fetch(", "XMLHttpRequest", "navigator.sendBeacon"] {
486	            assert!(
487	                !out.contains(forbidden),
488	                "landscape UI must not call back into anything ({forbidden} found)"
489	            );
490	        }
491	    }
492	
493	    /// Defense forms only exist in a defense landscape.
494	    #[test]
495	    fn html_omits_defense_forms_and_records_without_defense() {
496	        let out = html(false);
497	        for target in [
498	            "meta-stressor",
499	            "meta-attractor",
500	            "meta-purpose",
501	            "defense-persona",
502	            "defense-strategy",
503	            "defense-progress",
504	            "defense-pitch",
505	        ] {
506	            assert!(
507	                !out.contains(&format!(r#"data-command-generator="{target}""#)),
508	                "defense staging form for {target} must be absent without --defense"
509	            );
510	        }
511	        for needle in ["MS-01", "MA-01", "MP-01", "hostile-auditor", "alpha-strategy"] {
512	            assert!(
513	                !out.contains(needle),
514	                "defense record {needle} leaked into a non-defense landscape"
515	            );
516	        }
517	    }
518	
519	    #[test]
520	    fn html_includes_defense_forms_and_records_with_defense() {
521	        let out = html(true);
522	        for target in [
523	            "meta-stressor",
524	            "meta-attractor",
525	            "meta-purpose",
526	            "defense-persona",
527	            "defense-strategy",
528	            "defense-progress",
529	            "defense-pitch",
530	        ] {
531	            assert!(
532	                out.contains(&format!(r#"data-command-generator="{target}""#)),
533	                "defense staging form for {target} must be present with --defense"
