545	    /// Ledger text must not be able to close the embedded script block.
546	    #[test]
547	    fn html_escapes_script_terminator_in_snapshot_values() {
548	        let mut snap = fixture_main_snapshot();
549	        snap.stressors = vec![SnapshotForce {
550	            id: "S-01".into(),
551	            shortname: "xss".into(),
552	            description: "</script><script>alert(1)</script>".into(),
553	            naive_change: "add retry".into(),
554	            outcomes: "drain".into(),
555	            attractor_id: "A-01".into(),
556	            kind: ForceKind::Stressor,
557	            source: RecordSource::Sidecar,
558	        }];
559	
560	        let out = render_landscape_html(&snap).expect("landscape html renders");
561	        assert!(
562	            !out.contains("<script>alert(1)</script>"),
563	            "ledger text must not escape the embedded snapshot script block"
564	        );
565	    }
