567	    /// The template asset itself is the JS home — keep it wired, not empty.
568	    #[test]
569	    fn template_asset_carries_placeholder_and_generator_js() {
570	        assert!(
571	            TEMPLATE.contains(SNAPSHOT_PLACEHOLDER),
572	            "template must contain the snapshot JSON substitution token"
573	        );
574	        assert!(
575	            TEMPLATE.contains(SNAPSHOT_ELEMENT_ID),
576	            "template must contain the snapshot script element id"
577	        );
578	        assert!(
579	            TEMPLATE.contains("function buildAddCommand"),
580	            "template must define buildAddCommand"
581	        );
582	        assert!(
583	            TEMPLATE.contains("function shellQuote"),
584	            "template must define shellQuote"
585	        );
586	        assert!(
587	            TEMPLATE.contains("data-copy-commands"),
588	            "template must define the copy-commands surface"
589	        );
590	    }
591	}
