17	        --mono: "IBM Plex Mono", "JetBrains Mono", "SF Mono", ui-monospace, monospace;
18	        --sans: "IBM Plex Sans", "Source Sans 3", "Segoe UI", sans-serif;
19	      }
20	      * { box-sizing: border-box; }
