259	    <script>
260	      function shellQuote(value) {
261	        const s = String(value == null ? "" : value);
262	        if (s.indexOf("\n") !== -1 || s.indexOf("\r") !== -1) {
263	          let escaped = "";
264	          for (const ch of s) {
265	            if (ch === "\\") escaped += "\\\\";
266	            else if (ch === "'") escaped += "\\'";
267	            else if (ch === "\n") escaped += "\\n";
268	            else if (ch === "\r") escaped += "\\r";
269	            else if (ch === "\t") escaped += "\\t";
270	            else escaped += ch;
271	          }
272	          return "$'" + escaped + "'";
273	        }
274	        return "'" + s.replace(/'/g, "'\\''") + "'";
275	      }
276	
277	      function pushFlag(parts, flag, value) {
278	        parts.push(flag + " " + shellQuote(value));
279	      }
280	
281	      function pushOptionalFlag(parts, flag, value) {
282	        if (value != null && String(value) !== "") pushFlag(parts, flag, value);
283	      }
284	
285	      function buildAddCommand(target, fields) {
286	        const f = fields || {};
287	        const parts = ["residual add " + target];
288	        switch (target) {
289	          case "stressor":
290	          case "purpose":
291	          case "meta-purpose":
292	            pushFlag(parts, "--description", f.description || "");
293	            pushFlag(parts, "--attractor-id", f.attractor_id || "");
294	            pushFlag(parts, "--naive-change", f.naive_change || "");
295	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
296	            pushOptionalFlag(parts, "--outcomes", f.outcomes || "");
297	            break;
298	          case "attractor":
299	          case "meta-attractor":
300	            pushFlag(parts, "--name", f.name || "");
301	            pushFlag(parts, "--description", f.description || "");
302	            pushFlag(parts, "--positive-state", f.positive_state || "");
303	            pushFlag(parts, "--negative-state", f.negative_state || "");
304	            break;
305	          case "component":
306	            pushFlag(parts, "--name", f.name || "");
307	            pushFlag(parts, "--description", f.description || "");
308	            pushFlag(parts, "--status", f.status || "");
309	            pushFlag(parts, "--architecture-set", f.architecture_set || "");
310	            break;
311	          case "meta-stressor":
312	            pushFlag(parts, "--description", f.description || "");
313	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
314	            break;
315	          case "defense-persona":
316	          case "defense-strategy":
317	          case "defense-progress":
318	          case "defense-pitch":
319	            pushFlag(parts, "--name", f.name || "");
320	            pushFlag(parts, "--body", f.body || "");
321	            break;
322	          default:
323	            throw new Error("unknown add target: " + target);
324	        }
325	        return parts.join(" ");
326	      }
327	
328	      function formFields(form) {
329	        const data = {};
330	        for (const el of form.querySelectorAll("input, textarea, select")) {
331	          if (!el.name) continue;
332	          data[el.name] = el.value;
333	        }
334	        return data;
335	      }
336	
337	      function appendStaged(command) {
338	        const box = document.getElementById("staged-commands");
339	        box.value = box.value ? box.value + "\n" + command : command;
340	      }
341	
342	      document.querySelectorAll("form[data-command-generator]").forEach((form) => {
343	        form.addEventListener("submit", (ev) => {
344	          ev.preventDefault();
345	          const target = form.getAttribute("data-command-generator");
346	          appendStaged(buildAddCommand(target, formFields(form)));
347	        });
348	      });
349	
350	      const filterInput = document.querySelector("[data-force-filter]");
351	      if (filterInput) {
352	        filterInput.addEventListener("input", () => {
353	          const q = filterInput.value.trim().toLowerCase();
354	          document.querySelectorAll(".force-row, .component-chip").forEach((row) => {
355	            const hay = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();
356	            row.hidden = q !== "" && hay.indexOf(q) === -1;
357	          });
358	          document.querySelectorAll("[data-attractor-group]").forEach((group) => {
359	            const visible = group.querySelectorAll(".force-row:not([hidden])").length > 0;
360	            group.hidden = q !== "" && !visible;
361	          });
362	        });
363	      }
364	
365	      const copyBtn = document.getElementById("copy-staged");
366	      if (copyBtn) {
367	        copyBtn.addEventListener("click", async () => {
368	          const box = document.getElementById("staged-commands");
369	          if (navigator.clipboard && navigator.clipboard.writeText) {
370	            await navigator.clipboard.writeText(box.value);
371	          } else {
372	            box.select();
373	            document.execCommand("copy");
374	          }
375	        });
376	      }
377	      const clearBtn = document.getElementById("clear-staged");
378	      if (clearBtn) {
379	        clearBtn.addEventListener("click", () => {
380	          document.getElementById("staged-commands").value = "";
381	        });
382	      }
383	    </script>
